<template><el-card shadow="hover"><template #header><div class="header"><span>厅每日流水</span><div><span class="summary">最近成功同步时间：{{summary.finishedAt||'-'}}</span><el-button type="warning" :loading="syncing" @click="runSync">同步厅数据</el-button></div></div></template><VVSyncProgress sync-type="HALL_DATA" :active="syncing" />
	<el-table v-loading="table.loading" :data="table.list" border stripe><el-table-column prop="statDate" label="日期" width="110"/><el-table-column prop="hallName" label="厅名" min-width="140"/><el-table-column prop="hallId" label="厅号" width="90"/><el-table-column prop="roomId" label="roomId" width="115"/><el-table-column prop="rank" label="排名" width="75"/><el-table-column prop="totalFlow" label="总流水" width="110"/><el-table-column prop="totalLiveDiamond" label="钻石流水" width="110"/><el-table-column prop="enterRoomUser" label="进房人数" width="100"/><el-table-column prop="sendGiftPersonNum" label="送礼人数" width="100"/><el-table-column prop="enterRoomNewUser" label="新进房用户" width="110"/><el-table-column prop="roomPayNewUser" label="新进房送礼" width="110"/><el-table-column prop="enterRoomNewUser24h" label="24h进房新用户" width="130"/><el-table-column prop="roomPayNewUser24h" label="24h新用户送礼" width="130"/><el-table-column prop="newUserTotalFlow24h" label="24h新用户流水" width="130"/></el-table><pagination v-show="table.total>0" v-model:page="table.pageNum" v-model:limit="table.pageSize" :total="table.total" @pagination="load"/></el-card></template>
<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{getFlowDataDaily,getFlowDataSummary,syncFlowData}from'/@/api/system/flowData';import VVSyncProgress from'/@/components/vvSyncProgress/index.vue';defineOptions({name:'flowDataDaily'});const syncing=ref(false);const summary=reactive({finishedAt:''});const table=reactive({list:[]as any[],total:0,pageNum:1,pageSize:20,loading:false});const load=async()=>{table.loading=true;try{const r:any=await getFlowDataDaily({pageNum:table.pageNum,pageSize:table.pageSize});table.list=r.data.list??[];table.total=r.data.total??0;}finally{table.loading=false;}};const loadSummary=async()=>Object.assign(summary,(await getFlowDataSummary()as any).data);const runSync=async()=>{await ElMessageBox.confirm('确认同步厅数据？','同步确认',{type:'warning'});syncing.value=true;try{const r:any=await syncFlowData();ElMessage.success(`同步成功：新增 ${r.data.insertedCount}，更新 ${r.data.updatedCount}`);await Promise.all([load(),loadSummary()]);}finally{syncing.value=false;}};onMounted(()=>Promise.allSettled([load(),loadSummary()]));</script>
<style scoped>.header{display:flex;justify-content:space-between;align-items:center}.summary{margin-right:16px;color:var(--el-text-color-secondary)}</style>
